//! 🧪️ Real original producer, Work and construction owners settle independent errors.
use super::*;
use semio_framework_value_control_contract as core;
use semio_framework_value_receiving::span::effect::*;
struct Work;
impl core::OriginalWorkRecipient for Work{
 type Context<'a,'b>=&'a core::OriginalSourceTurn where 'b:'a;
 fn validate_context<'a,'b>(&self,_:&Self::Context<'a,'b>)->Result<(),ValueError> where 'b:'a{Ok(())}
 fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<core::OriginalSourceTurnIdentity> where 'b:'a{Some(c.identity())}
 fn admits<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,q:core::OriginalWorkQuote<'r>,_:u64,_:u64)->core::OriginalWorkQuoteComplete<'r> where 'b:'a{q.complete(Ok(true))}
 fn settle_partial<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,q:core::OriginalWorkPartialCheck<'r>)->core::OriginalWorkPartialCheckComplete<'r> where 'b:'a{q.complete(Ok(()))}
 fn recover_partial<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,q:core::OriginalWorkPartialCheck<'r>)->core::OriginalWorkPartialCheckComplete<'r> where 'b:'a{q.pending()}
}
struct Physical{progress:RetainedCloneProgress,error:Option<ValueError>}
impl core::OriginalConstructionRecipient for Physical{
 type Context<'a,'b>=&'a core::OriginalSourceTurn where 'b:'a;
 fn validate_context<'a,'b>(&self,_:&Self::Context<'a,'b>)->Result<(),ValueError> where 'b:'a{Ok(())}
 fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<core::OriginalSourceTurnIdentity> where 'b:'a{Some(c.identity())}
 fn submitted<'a,'b>(&self,_:&Self::Context<'a,'b>)->RetainedCloneProgress where 'b:'a{self.progress}
 fn grant<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,q:core::OriginalConstructionGrant<'r>)->core::OriginalConstructionGrantComplete<'r> where 'b:'a{q.complete(Ok(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:16,maximum_depth:1,..Default::default()}))}
 fn accept<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,q:core::OriginalConstructionAccept<'r>)->core::OriginalConstructionAcceptComplete<'r> where 'b:'a{self.progress=q.progress();q.complete(self.error.take().map_or(Ok(()),Err))}
}
struct Producer{error:Option<ValueError>,calls:usize,input:[u8;8],output:[u8;8]}
impl OriginalEffectProducer for Producer{
 type Output=NativeEncodeProducerOutcome;type Failure=NativeEncodeProducerFailure;type Context<'a,'b>=&'a core::OriginalSourceTurn where 'b:'a;
 fn validate_context<'a,'b>(&self,_:&Self::Context<'a,'b>)->Result<(),ValueError> where 'b:'a{Ok(())}
 fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<core::OriginalSourceTurnIdentity> where 'b:'a{Some(c.identity())}
 fn receive<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,effect:&mut core::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,NativeEncodeProducerOutcome,NativeEncodeProducerFailure>)->Result<OriginalEffectReplyComplete<'r,NativeEncodeProducerOutcome,NativeEncodeProducerFailure>,ValueError> where 'b:'a{self.calls+=1;assert!(effect.performed(1).unwrap());self.output.copy_from_slice(&self.input);let _reply=reply.complete(Err(NativeEncodeProducerFailure{performed:true,progress:RetainedCloneProgress{copied_items:1,copied_bytes:8,..Default::default()},cause:self.error.take().unwrap()}));panic!("actual producer interrupted after reply")}
 fn recover<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,_:&mut core::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,NativeEncodeProducerOutcome,NativeEncodeProducerFailure>)->Result<OriginalEffectReplyComplete<'r,NativeEncodeProducerOutcome,NativeEncodeProducerFailure>,ValueError> where 'b:'a{Ok(reply.pending())}
}
struct FiniteWork{source:core::OriginalSourceTurnIdentity,left:u128}
impl core::OriginalWorkRecipient for FiniteWork{
 type Context<'a,'b>=&'a core::OriginalSourceTurn where 'b:'a;
 fn validate_context<'a,'b>(&self,c:&Self::Context<'a,'b>)->Result<(),ValueError> where 'b:'a{if c.identity()==self.source{Ok(())}else{Err(ValueError::invariant("foreign original Source"))}}
 fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<core::OriginalSourceTurnIdentity> where 'b:'a{Some(c.identity())}
 fn admits<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,q:core::OriginalWorkQuote<'r>,_:u64,units:u64)->core::OriginalWorkQuoteComplete<'r> where 'b:'a{q.complete(Ok(u128::from(units)<=self.left))}
 fn settle_partial<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,q:core::OriginalWorkPartialCheck<'r>)->core::OriginalWorkPartialCheckComplete<'r> where 'b:'a{let result=self.validate_context(c).and_then(|()|{self.left=self.left.checked_sub(q.delta()).ok_or_else(||ValueError::literal(core::ValueRefusalKind::WorkLimit,"finite Source work exhausted"))?;Ok(())});q.complete(result)}
 fn recover_partial<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,q:core::OriginalWorkPartialCheck<'r>)->core::OriginalWorkPartialCheckComplete<'r> where 'b:'a{q.pending()}
}
struct FinitePhysical{source:core::OriginalSourceTurnIdentity,left:RetainedCloneGrant,progress:RetainedCloneProgress,error:Option<ValueError>,payout_error:Option<ValueError>,interrupt_payout:bool,calls:std::sync::Arc<std::sync::atomic::AtomicUsize>}
impl core::OriginalConstructionRecipient for FinitePhysical{
 type Context<'a,'b>=&'a core::OriginalSourceTurn where 'b:'a;
 fn validate_context<'a,'b>(&self,c:&Self::Context<'a,'b>)->Result<(),ValueError> where 'b:'a{if c.identity()==self.source{Ok(())}else{Err(ValueError::invariant("foreign original Source"))}}
 fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<core::OriginalSourceTurnIdentity> where 'b:'a{Some(c.identity())}
 fn submitted<'a,'b>(&self,_:&Self::Context<'a,'b>)->RetainedCloneProgress where 'b:'a{self.progress}
 fn grant<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,q:core::OriginalConstructionGrant<'r>)->core::OriginalConstructionGrantComplete<'r> where 'b:'a{let d=q.demand();let grant=RetainedCloneGrant{maximum_items:usize::from(self.left.maximum_items>0),maximum_copy_bytes:d.copy_bytes.min(self.left.maximum_copy_bytes),maximum_capacity_bytes:d.capacity_bytes.min(self.left.maximum_capacity_bytes),maximum_release_bytes:d.release_bytes.min(self.left.maximum_release_bytes),maximum_depth:d.depth.min(self.left.maximum_depth)};q.complete(Ok(grant))}
 fn accept<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,q:core::OriginalConstructionAccept<'r>)->core::OriginalConstructionAcceptComplete<'r> where 'b:'a{let progress=q.progress();assert!(progress.fits(self.left));self.left.maximum_items-=progress.copied_items;self.left.maximum_copy_bytes-=progress.copied_bytes;self.left.maximum_capacity_bytes-=progress.retained_capacity_bytes;self.left.maximum_release_bytes-=progress.released_bytes;self.progress=self.progress.checked_add(progress).unwrap();let ordinal=self.calls.fetch_add(1,std::sync::atomic::Ordering::SeqCst)+1;let error=self.error.take().or_else(||if ordinal==3{self.payout_error.take()}else{None});let reply=q.complete(error.map_or(Ok(()),Err));if self.interrupt_payout&&progress.copied_bytes>8{self.interrupt_payout=false;panic!("original finite Source recorded payout before unwind")}reply}
}
#[derive(Default)]
struct Payment{maximum_work:u64,physical:Option<core::OriginalConstructionAction>,action:Option<core::OriginalWorkActionIdentity>,receipt:Option<core::OriginalWorkPerformedReceipt>,claim:Option<Result<u128,ValueError>>,partial:Option<core::OriginalWorkPartialOutcome>,proof:Option<core::OriginalWorkActionProof>,actual:Option<usize>,progress:Option<RetainedCloneProgress>}
impl Payment{
 fn begin(&mut self,work:&mut core::OriginalWork<'_>,physical:&mut core::OriginalConstructionLoan<'_>,demand:RetirementDemand){self.begin_units(work,physical,demand,1)}
 fn begin_units(&mut self,work:&mut core::OriginalWork<'_>,physical:&mut core::OriginalConstructionLoan<'_>,demand:RetirementDemand,maximum_work:u64){self.maximum_work=maximum_work;let mut borrow=core::OriginalWorkBorrow::new(work);physical.begin(demand,&mut self.physical,&borrow).unwrap();physical.quote(self.physical.as_mut().unwrap()).unwrap();assert!(physical.recover_grant(self.physical.as_mut().unwrap()).unwrap().unwrap().is_ok());assert_eq!(borrow.prepare(maximum_work,&mut self.action).unwrap(),Some(true))}
 fn stage(&mut self,work:&mut core::OriginalWork<'_>,physical:&mut core::OriginalConstructionLoan<'_>,operation:impl FnOnce(&mut core::OriginalConstructionLoan<'_>,&core::OriginalConstructionAction,&mut core::RetainedAllocationEffect<'_>)->core::RetainedWorkOutcome<Option<RetainedCloneProgress>,ValueError>){let mut borrow=core::OriginalWorkBorrow::new(work);if let Some(claim)=self.claim.take(){claim.unwrap();if borrow.partial_pending(self.action).unwrap(){assert!(borrow.settle_partial_into(self.action,&mut self.partial).unwrap());assert!(self.partial.as_ref().unwrap().source_refusal().is_none());drop(self.partial.take())}}let spent=borrow.performed_total(self.action).unwrap();let remaining=u64::try_from(u128::from(self.maximum_work).checked_sub(spent).expect("original work exceeded its quote")).unwrap();let mut scope=borrow.performed_scope(self.action,&mut self.receipt,&mut self.claim).unwrap();let grant=self.physical.as_ref().unwrap().grant().unwrap();let mut effect=scope.effect(grant,remaining,&mut self.actual).unwrap();let turn=operation(physical,self.physical.as_ref().unwrap(),&mut effect);assert_eq!(turn.work,effect.performed_work());self.progress=turn.result.unwrap();assert!(self.progress.is_some())}
 fn settle(&mut self,work:&mut core::OriginalWork<'_>,physical:&mut core::OriginalConstructionLoan<'_>)->bool{let mut borrow=core::OriginalWorkBorrow::new(work);if self.proof.is_none(){if let Some(claim)=self.claim.take(){claim.unwrap();}if borrow.partial_pending(self.action).unwrap(){assert!(borrow.settle_partial_into(self.action,&mut self.partial).unwrap());assert!(self.partial.as_ref().unwrap().source_refusal().is_none());drop(self.partial.take())}let total=borrow.performed_total(self.action).unwrap();assert!(borrow.commit(total,self.action,&mut self.proof).unwrap())}let action=self.physical.as_mut().unwrap();if action.phase()==core::OriginalConstructionPhase::Granted{physical.post(action,self.progress.unwrap(),self.actual).unwrap()}if action.phase()==core::OriginalConstructionPhase::AcceptStarted&&physical.recover_accept(action).unwrap().is_none(){return false}action.recorded_accept_status()==Some(core::OriginalConstructionAcceptStatus::Accepted)}
 fn finish_retained(&mut self,work:&mut core::OriginalWork<'_>){core::OriginalWorkBorrow::new(work).finish_retained(&mut self.proof,&mut self.action).unwrap()}
 fn finish(&mut self,work:&mut core::OriginalWork<'_>,physical:&mut core::OriginalConstructionLoan<'_>){core::OriginalWorkBorrow::new(work).finish(&mut self.proof,&mut self.action).unwrap();physical.finish_accepted(&mut self.physical).unwrap()}
}
