  let mut retry=Payment::default();{let port=construction.as_deref_mut().unwrap();retry.begin(&mut work,port,crate::OriginalReceivingPrimary::receipt_completion_retry_demand());retry.stage(&mut work,port,|port,payout,effect|state.as_mut().unwrap().retry_published_receipt(port,payout_refusal.as_ref().unwrap(),payout,effect));assert!(retry.settle(&mut work,port))}{let mut recovery=NativeEncodeEffectRecovery::new(&mut work,&mut construction,Some(identity));assert!(recovery.publish_refused_receipt(&mut state,retry.physical.as_ref().unwrap(),retry.proof.as_ref().unwrap()).unwrap())}{let port=construction.as_deref_mut().unwrap();retry.finish(&mut work,port)}
  let mut payout_release=Payment::default();{let port=construction.as_deref_mut().unwrap();let demand=payout_refusal.as_ref().unwrap().release_demand();payout_release.begin(&mut work,port,demand);payout_release.stage(&mut work,port,|port,payout,effect|port.retire_completion(&mut payout_refusal,payout,effect));assert!(payout_release.settle(&mut work,port));payout_release.finish(&mut work,port)}assert!(payout_refusal.is_none());
  let mut failure=Some(NativeEncodeEffectFailure::default());let mut denied=Payment::default();{let port=construction.as_deref_mut().unwrap();denied.begin(&mut work,port,NativeEncodeEffectSettlement::failure_transfer_demand().unwrap());{let mut borrow=core::OriginalWorkBorrow::new(&mut work);let mut scope=borrow.performed_scope(denied.action,&mut denied.receipt,&mut denied.claim).unwrap();let mut effect=scope.effect(denied.physical.as_ref().unwrap().grant().unwrap(),0,&mut denied.actual).unwrap();foreign.with_loan(&mut &turn,|other|{assert!(NativeEncodeEffectSettlement::finish_into_paid(&mut state,failure.as_mut().unwrap(),other,denied.physical.as_ref().unwrap(),&mut effect).result.is_err());assert!(state.is_some()&&failure.as_ref().unwrap().is_empty());Ok::<_,ValueError>(())}).unwrap().unwrap();assert!(NativeEncodeEffectSettlement::finish_into_paid(&mut state,failure.as_mut().unwrap(),port,denied.physical.as_ref().unwrap(),&mut effect).result.unwrap().is_none())}assert!(state.is_some()&&failure.as_ref().unwrap().is_empty());assert_eq!(denied.claim.take().unwrap().unwrap(),0);core::OriginalWorkBorrow::new(&mut work).cancel(&mut denied.action).unwrap();port.cancel(denied.physical.as_mut().unwrap(),false,Default::default(),None).unwrap();port.finish(&mut denied.physical).unwrap()}let mut transfer=Payment::default();{let port=construction.as_deref_mut().unwrap();transfer.begin(&mut work,port,NativeEncodeEffectSettlement::failure_transfer_demand().unwrap());transfer.stage(&mut work,port,|port,payout,effect|NativeEncodeEffectSettlement::finish_into_paid(&mut state,failure.as_mut().unwrap(),port,payout,effect));assert!(transfer.settle(&mut work,port));transfer.finish(&mut work,port)}assert!(law[2]["visible"].as_bool().unwrap());assert_eq!(failure.as_ref().unwrap().physical_receipt.as_ref().unwrap().receipt_completion().unwrap().message.as_ptr(),physical_pointer);
  let mut output=Payment::default();{let port=construction.as_deref_mut().unwrap();output.begin(&mut work,port,OriginalEffectAuthority::<Producer>::transfer_reply_demand().unwrap());output.stage(&mut work,port,|_,_,effect|producer.transfer_reply_into(&&turn,&mut action,&mut reply,effect));assert!(output.settle(&mut work,port));output.finish(&mut work,port)}let outcome=reply.as_ref().unwrap().as_ref().unwrap_err();assert!(outcome.performed);assert_eq!(outcome.progress,progress);assert_eq!(outcome.cause.message.as_ptr(),source_pointer);let receiving=failure.as_mut().unwrap().physical_receipt.as_mut().unwrap();let demand=receiving.receipt_completion_release_demand().unwrap().unwrap();let mut release=Payment::default();{let port=construction.as_deref_mut().unwrap();release.begin(&mut work,port,demand);release.stage(&mut work,port,|port,payout,effect|receiving.retire_receipt_completion(port,payout,effect));assert!(release.settle(&mut work,port));release.finish(&mut work,port);error_retirement::retire(&turn,&mut work,port,&mut reply);let demand=RetirementDemand{copy_bytes:size_of::<Option<NativeEncodeEffectFailure>>(),depth:1,..Default::default()};let mut release=Payment::default();release.begin(&mut work,port,demand);release.stage(&mut work,port,|_,_,effect|{assert!(effect.performed(1).unwrap());drop(failure.take());core::RetainedWorkOutcome{result:Ok(Some(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()})),work:1}});assert!(release.settle(&mut work,port));release.finish(&mut work,port)}assert!(failure.is_none());work_total=work.actual();
