struct QuotedWork<'a>{source:core::OriginalSourceTurnIdentity,maximum:u64,observed:&'a std::sync::atomic::AtomicU64}
impl core::OriginalWorkRecipient for QuotedWork<'_>{
 type Context<'a,'b>=&'a core::OriginalSourceTurn where 'b:'a;
 fn validate_context<'a,'b>(&self,c:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{if c.identity()==self.source{Ok(())}else{Err(ValueError::invariant("foreign original Work Source"))}}
 fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<core::OriginalSourceTurnIdentity>where 'b:'a{Some(c.identity())}
 fn admits<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,reply:core::OriginalWorkQuote<'r>,observed:u64,additional:u64)->core::OriginalWorkQuoteComplete<'r>where 'b:'a{self.observed.store(additional,std::sync::atomic::Ordering::Relaxed);reply.complete(Ok(observed.checked_add(additional).is_some_and(|n|n<=self.maximum)))}
 fn settle_partial<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,reply:core::OriginalWorkPartialCheck<'r>)->core::OriginalWorkPartialCheckComplete<'r>where 'b:'a{reply.complete(self.validate_context(c))}
 fn recover_partial<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,reply:core::OriginalWorkPartialCheck<'r>)->core::OriginalWorkPartialCheckComplete<'r>where 'b:'a{reply.complete(self.validate_context(c))}
}
#[test]
fn original_encoder_effect_keeps_explicit_work_quote(){
 let law:serde_json::Value=serde_json::from_str(include_str!("work-quote.json")).unwrap();
 for row in law["cases"].as_array().unwrap(){let issuer=core::OriginalSourceTurnIssuer::new();let turn=issuer.issue().unwrap();let quoted=std::sync::atomic::AtomicU64::new(u64::MAX);let maximum=row["maximum"].as_u64().unwrap();let actual_work=row["actual"].as_u64().unwrap();let accepted=row["accepted"].as_bool().unwrap();let mut payer=core::OriginalWorkAuthority::new(QuotedWork{source:turn.identity(),maximum:law["sourceWork"].as_u64().unwrap(),observed:&quoted});let mut physical=core::OriginalConstructionAuthority::new(Physical{progress:Default::default(),error:None});let mut state=None;
 payer.with_loan(&mut &turn,|work_loan|physical.with_loan(&mut &turn,|physical_loan|{let identity=physical_loan.identity();let mut work_loan=work_loan.reborrow();let mut physical_loan=physical_loan.reborrow();let mut construction=Some(&mut physical_loan);let mut work=core::OriginalWork::empty();work.recipient=Some(&mut work_loan);let begun=NativeEncodeEffectRecovery::new(&mut work,&mut construction,Some(identity)).begin(&mut state,RetirementDemand{depth:1,..Default::default()},maximum);assert_eq!(quoted.load(std::sync::atomic::Ordering::Relaxed),maximum);if !accepted{assert!(begun.is_err());NativeEncodeEffectRecovery::new(&mut work,&mut construction,Some(identity)).release_refused(&mut state).unwrap();assert!(state.is_none());return}assert!(begun.unwrap());assert_eq!(state.as_ref().unwrap().maximum_work(),maximum);let mut receipt=None;{let mut loan=core::OriginalWorkTurn::new(&mut work);state.as_ref().unwrap().issue_performed(&mut loan,&mut receipt).unwrap()}let mut marker=None;{let mut effect=core::RetainedAllocationEffect::new(state.as_ref().unwrap().quoted_grant().unwrap(),maximum,&mut marker,receipt.as_mut().unwrap());assert_eq!(effect.maximum_work_units(),maximum);assert_eq!(effect.work_source_turn(),Some(turn.identity()));let mut completed=0;if actual_work==0{assert!(effect.performed(0).unwrap())}for _ in 0..actual_work{assert!(effect.performed(1).unwrap());completed+=1;}assert_eq!(completed,actual_work)}{let mut loan=core::OriginalWorkTurn::new(&mut work);state.as_ref().unwrap().claim_performed(&mut loan,&mut receipt).unwrap();let mut partial=None;assert!(state.as_ref().unwrap().settle_performed_into(&mut loan,&mut partial).unwrap());let partial=partial.take().unwrap();assert_eq!(partial.delta(),u128::from(actual_work));assert!(partial.source_refusal().is_none());assert_eq!(state.as_ref().unwrap().performed_total(&loan).unwrap(),u128::from(actual_work));assert!(state.as_mut().unwrap().record_performed_before_post(&mut loan,Default::default(),true,None).unwrap())}assert!(NativeEncodeEffectRecovery::new(&mut work,&mut construction,Some(identity)).settle(&mut state).unwrap());let mut failure=NativeEncodeEffectFailure::default();assert!(NativeEncodeEffectSettlement::finish_into(&mut state,&mut failure).unwrap());assert!(failure.is_empty());assert!(state.is_none());}).unwrap()).unwrap();assert!(!payer.has_live_actions());assert!(physical.into_recipient().is_ok());}
}

#[test]
fn producer_success_is_copy_and_failure_keeps_actual_physical_cause(){
 fn copies<T:Copy>(value:T)->(T,T){(value,value)}
 let law:serde_json::Value=serde_json::from_str(include_str!("producer.json")).unwrap();let progress=RetainedCloneProgress{copied_items:law["success"]["copiedItems"].as_u64().unwrap()as usize,copied_bytes:law["success"]["copiedBytes"].as_u64().unwrap()as usize,..Default::default()};let success=NativeEncodeProducerOutcome{performed:law["success"]["performed"].as_bool().unwrap(),progress};let(first,second)=copies(success);assert_eq!(first.performed,second.performed);assert_eq!(first.progress,second.progress);let cause=ValueError::new(ValueRefusalKind::Canceled,law["failure"]["cause"].as_str().unwrap().to_owned());let pointer=cause.message.as_ptr();let failure=NativeEncodeProducerFailure{performed:law["failure"]["performed"].as_bool().unwrap(),progress,cause};assert_eq!(failure.progress.copied_items,law["failure"]["copiedItems"].as_u64().unwrap()as usize);assert_eq!(failure.progress.copied_bytes,law["input"].as_str().unwrap().len());assert!(failure.performed);assert_eq!(failure.cause.message.as_ptr(),pointer);assert!(crate::retirement::RetireOwned::retirement_ready(&failure));
}
